(3, 3, 'Mary Help of Christians Parish', 'mary-help-of-christians-parish', '<p>The historic Saint Enrique Parish Church, a centuries-old architectural marvel that stands as a testament to the rich cultural heritage of the municipality.</p>', 'Poblacion, San Enrique', 'Poblacion', '', '', '', '11.07294038', '122.65644729', 'https://lh3.googleusercontent.com/d/1lcRZlKw4-LNy7ok1lvallBeNKY-cBqUz', '[]', '', 'Open Daily', '', '', '', '', 'active', 0, 3, '0.00', '2026-03-22 14:09:14', '2026-05-25 01:46:46'),
(8, 2, 'Barangay Asisig', 'barangay-asisig', 'Classified as a small barangay, Barangay Asisig is one of the administrative divisions of San Enrique in Iloilo, Western Visayas, Philippines. Barangay Asisig had a population of 888. This made it the 22nd largest of 28 barangays in San Enrique by population, placing it among the smaller barangays of the municipality. Residents of Barangay Asisig accounted for approximately 2.38% of the total population of San Enrique.<br><br>Local Products:<br><b>Sugarcane / Muscovado • Traditional mat weaving (banig) • Handcraft production</b><br><br>Officials:<br><br>Punong Barangay<div><b>Myrna Pamplona Patubo (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Melalyn Dalipe Sicula</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Mary Love Diaz Tabion</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>Jay-bee Canja</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Daisy Jimenez Padernal</b></li><li><b>Evelyn Dava Delima</b></li><li><b>Andy Jun Pamonag Aguilar</b></li><li><b>Ma. Lina Porras Panes</b></li><li><b>Leandro Albania Palma</b></li><li><b>Fredolin Periorico Dalipe</b></li><li><b>Rexel Arellano Albania</b></li></ul></div>', 'Barangay Asisig, San Enrique, Iloilo', 'Asisig', '', '', 'https://www.facebook.com/groups/223302368894780', '11.10568862', '122.67145496', 'https://lh3.googleusercontent.com/d/15QuC_8lPcbjVeY7HBFFOAbduXO-I3hPU', '[]', '', '', '', '', '6.4 km', '888', 'active', 0, 13, '0.00', '2026-03-22 14:09:14', '2026-07-05 06:13:52'),
(9, 2, 'Barangay Bantayan', 'barangay-bantayan', 'Barangay Bantayan forms part of San Enrique, a municipality in Iloilo, and is classified as a small barangay. Barangay Bantayan had a population of 1,113. This made it the 18th largest of 28 barangays in San Enrique by population, placing it in the middle tier of the municipality. Residents of Barangay Bantayan accounted for approximately 2.98% of the total population of San Enrique.<br><br>Local Products:<br><b>Sugarcane / Muscovado • Bamboo furniture • Basket-making</b><br><br>Officials:<br><br>Punong Barangay<div><b>Aristeo Zulueta Baldonado (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Marcelina Saludaris Castañeda</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Eustine Pagayona Pama</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>John Kenneth Pama</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Ronabeth Estante Consemino</b></li><li><b>Gemma Acuyong Lademora</b></li><li><b>Annamarie Laus Tablac</b></li><li><b>Dionisio Capioso Biana</b></li><li><b>Heda Pama Abalecio</b></li><li><b>Rodolfo Paclibar Jiz JR.</b></li><li><b>Margie Concepcion Laus</b></li></ul></div>', 'Barangay Bantayan, San Enrique, Iloilo', 'Bantayan', '', '', '', '11.08706339', '122.69278188', 'https://lh3.googleusercontent.com/d/1SQhwXQSKYJwxZJhzatDEh5XiFI5KCdoe', '[]', '', '', '', '', '6.8 km', '1,113', 'active', 0, 14, '0.00', '2026-03-22 14:09:14', '2026-06-14 06:07:17'),
(10, 2, 'Barangay Braulan', 'barangay-braulan', 'Situated in San Enrique, Iloilo, Barangay Braulan is one of 28 barangays that make up the municipality within Western Visayas. Barangay Braulan had a population of 1,458. This made it the 13th largest of 28 barangays in San Enrique by population, placing it in the middle tier of the municipality. Residents of Barangay Braulan accounted for approximately 3.90% of the total population of San Enrique.<br><br>Local Products:<br><b>Sugarcane / Muscovado • Agricultural crops</b><br><br>Officials:<br><br>Punong Barangay<div><b>Darwin Alarba Solas (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Josie Alim Javier</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Gina Alim Libalib</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>George Parreno</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Ma. Dolores Pacardo Pagaypay</b></li><li><b>Ronel Banatasa Aguilar</b></li><li><b>Regie Aguilar Alarba</b></li><li><b>Melecio Alim Alarba JR.</b></li><li><b>Romeo Panizales Paturara</b></li><li><b>Johny Panes Palomo</b></li><li><b>Greg Minor Alarba</b></li></ul></div>', 'Barangay Braulan, San Enrique, Iloilo', 'Braulan', '', '', 'https://www.facebook.com/profile.php?id=61553682964106', '11.13591262', '122.73798886', 'https://lh3.googleusercontent.com/d/1cxjrRf4JE48Y3hY7l614QwpdANjSpfKM', '[]', '', '', '', '', '14.5 km', '1,458', 'active', 0, 3, '0.00', '2026-03-22 14:09:14', '2026-06-01 02:13:41'),
(11, 2, 'Barangay Cabugao Nuevo', 'barangay-cabugao-nuevo', 'Is a very small barangay in the municipality of San Enrique, located in the province of Iloilo, in the Western Visayas region of the Philippines. Barangay Cabugao Nuevo had a population of 243. This made it the 28th largest of 28 barangays in San Enrique by population, placing it among the smaller barangays of the municipality. Residents of Barangay Cabugao Nuevo accounted for approximately 0.65% of the total population of San Enrique.<br><br>Local Products:<br><b>Sugarcane / Muscovado • Traditional mat weaving (banig) • Handcraft production</b><br><br>Officials:<br><br>Punong Barangay<div><b>Allan Gadia Pabillona (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Maria Regina Calsado Cajandig</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Concepcion Paclibar De La Cruz</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>Robert Dajay</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Jocelyn Barbecho Paclibar</b></li><li><b>Mariza Suobiron Gadia</b></li><li><b>Roselyn Mariano Marcelo</b></li><li><b>Wilfredo Paclijan Darroca JR.</b></li><li><b>Eva Palabrica Pedotin</b></li><li><b>Jasfer Salmeron Cajandig</b></li><li><b>Ronald Asano Penetrante</b></li></ul></div>', 'Barangay Cabugao Nuevo, San Enrique, Iloilo', 'Cabugao Nuevo', '', '', '', '11.07133335', '122.67173606', 'https://lh3.googleusercontent.com/d/1QVTs4XMGT6X6EBsUXIqcsw63Gqu0IWvf', '[]', '', '', '', '', '4 km', '243', 'active', 0, 3, '0.00', '2026-03-22 14:09:14', '2026-06-01 02:13:50'),
(12, 2, 'Barangay Cabugao Viejo', 'barangay-cabugao-viejo', 'Classified as a small barangay, Barangay Cabugao Viejo is one of the administrative divisions of San Enrique in Iloilo, Western Visayas, Philippines. Barangay Cabugao Viejo had a population of 1,570. This made it the 11th largest of 28 barangays in San Enrique by population, placing it in the middle tier of the municipality. Residents of Barangay Cabugao Viejo accounted for approximately 4.20% of the total population of San Enrique.<br><br>Local Products:<br><b>Sugarcane / Muscovado • Traditional mat weaving (banig) • Handcraft production</b><br><br>Officials:<br><br>Punong Barangay<div><b>Wilfredo Margate Medianesta (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Gerame Bergante Zante</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Vicente Pabilona Leonor</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>Alfonso Agramon JR.</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Lucilo Pabilona Leonor</b></li><li><b>Mary Caballar Aguilar</b></li><li><b>Aireen Sayson Pabilona</b></li><li><b>Joel Salde Agudon</b></li><li><b>Edmund Diongson Dativo</b></li><li><b>Vincent Palermo Maglapit</b></li><li><b>Ekeson Palomo Palomo</b></li></ul></div>', 'Barangay Cabugao Viejo, San Enrique, Iloilo', 'Cabugao Viejo', '', '', 'https://www.facebook.com/groups/213430483312531', '11.07205077', '122.66318188', 'https://lh3.googleusercontent.com/d/181t3ikUdOy0bmSIzGn0Sx2cPwYuhEnI6', '[]', '', '', '', '', '3 km', '1,570', 'active', 0, 2, '0.00', '2026-03-22 14:09:14', '2026-06-11 07:15:08'),
(13, 2, 'Barangay Camiri', 'barangay-camiri', 'Barangay Camiri forms part of San Enrique, a municipality in Iloilo, and is classified as a small barangay. Barangay Camiri had a population of 1,868. This made it the 6th largest of 28 barangays in San Enrique by population, placing it in the upper half of the municipality. Residents of Barangay Camiri accounted for approximately 5.00% of the total population of San Enrique. The simboryo of Barangay Camiri is a quiet yet striking reminder of the barangay&#039;s cultural heritage. Nestled within a serene environment, it stands as a witness to the passing of time and the resilience of local traditions. Its presence brings a sense of peace and continuity, reflecting the community&#039;s strong spiritual connection and respect for their history.<br><br>Local Products:<br><b>Milled rice • Corn • Root crops • Sugarcane / Muscovado</b><br><br>Officials:<br><br>Punong Barangay<div><b>Grace Mae Pama Lapasaran (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Jela Marie Solivio Armigos</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Hanna Mae Celiz</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>Benjo Miranda</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Nilo Pacaco Pama</b></li><li><b>Jarel Paclibar Palencia</b></li><li><b>Niño John Errol Palmes Benagera</b></li><li><b>Arnold Paclibar Garcia</b></li><li><b>Angelita Boaquiña Pacardo</b></li><li><b>Rey John Miranda Pama</b></li><li><b>Hernando Paderes Paltu-ob</b></li></ul></div>', 'Barangay Camiri, San Enrique, Iloilo', 'Camiri', '', '', 'https://www.facebook.com/profile.php?id=61565832921860', '11.08264153', '122.65384795', 'https://lh3.googleusercontent.com/d/1Bk7stSj8hqT2M0p1XnmrX1hZbB5dbPYK', '[]', '', '', '', '', '6 km', '1,868', 'active', 0, 2, '0.00', '2026-03-22 14:09:14', '2026-05-24 14:41:56'),
(14, 2, 'Barangay Compo', 'barangay-compo', 'Is one of 28 barangays that make up the municipality within Western Visayas. Barangay Compo had a population of 1,356. This made it the 14th largest of 28 barangays in San Enrique by population, placing it in the middle tier of the municipality. Residents of Barangay Compo accounted for approximately 3.63% of the total population of San Enrique.<br><br>Local Products:<br><b>Sugarcane / Muscovado • Agricultural crops</b><br><br>Officials:<br><br>Punong Barangay<div><b>Leo Paca-oncis Burcag (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Jocelyn Pamposa Burcag</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Mary Grace Panes Gabayeron</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>Kent Justine Burcag</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Albert Jabagat Paclibar</b></li><li><b>Gemma Lara Venus</b></li><li><b>Rowelyn Rose Catalogo Gabayeron</b></li><li><b>Theresa Pamposa Burcag</b></li><li><b>Ariel Banggay Cartagena</b></li><li><b>Ferdinand Cerbo Gonzales</b></li><li><b>Albert Casipe Comida</b></li></ul></div>', 'Barangay Compo, San Enrique, Iloilo', 'Compo', '', '', 'https://www.facebook.com/profile.php?id=100066410029706', '11.05672006', '122.65896291', 'https://lh3.googleusercontent.com/d/1PF24dubB3njOX7RFCt2a1z5reU6nWBCO', '[]', '', '', '', '', '5 km', '1,356', 'active', 0, 1, '0.00', '2026-03-22 14:09:14', '2026-05-24 14:42:27'),
(15, 2, 'Barangay Catan-Agan', 'barangay-catan-agan', 'Barangay Catan-Agan is a small barangay in the municipality of San Enrique, located in the province of Iloilo, in the Western Visayas region of the Philippines. Barangay Catan-Agan had a population of 1,689. This made it the 7th largest of 28 barangays in San Enrique by population, placing it in the upper half of the municipality. Residents of Barangay Catan-Agan accounted for approximately 4.52% of the total population of San Enrique.<br><br>Local Products:<br><b>Sugarcane / Muscovado • Agricultural crops</b><br><br>Officials:<br><br>Punong Barangay<div><b>Jun Jun Baasio Aguilar (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Ma. Chona Aguilar</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Asuncion Pector</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>Jerwin Granja</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Alan Palmares Aguilar</b></li><li><b>Edgar Umadhay Paclibar</b></li><li><b>Manuel Bendoy Agujitas JR</b></li><li><b>Cheren Bale Tiquio</b></li><li><b>Haydee Daria Palec</b></li><li><b>Ma. Recel Gomez Panes</b></li><li><b>Ghay Ann Alada</b></li></ul></div>', 'Barangay Catan-Agan, San Enrique, Iloilo', 'Catan-Agan', '', '', 'https://www.facebook.com/profile.php?id=100063789806327', '11.12410319', '122.74969667', 'https://lh3.googleusercontent.com/d/1OYHtcwxN6XDMRcoMcHfQ3eMLxY3hHPLs', '[]', '', '', '', '', '9 km', '1,689', 'active', 0, 1, '0.00', '2026-03-22 14:09:14', '2026-05-24 14:41:56'),
(16, 2, 'Barangay Cubay', 'barangay-cubay', 'Barangay Cubay forms part of San Enrique, a municipality in Iloilo, and is classified as a mid-sized barangay. Barangay Cubay had a population of 2,004. This made it the 4th largest of 28 barangays in San Enrique by population, placing it in the upper half of the municipality. Residents of Barangay Cubay accounted for approximately 5.36% of the total population of San Enrique. In Barangay Cubay, the simboryo rises as a symbol of unity and devotion. Its aged structure tells stories of shared beliefs and generations who have kept their faith alive. Often visited during moments of need or gratitude, it remains a sacred space that connects the past with the present, reminding the community of their enduring cultural identity.<br><br>Local Products:<br><b>Sugarcane / Muscovado • Bamboo furniture • Basket-making</b><br><br>Officials:<br><br>Punong Barangay<div><b>Jose Noel Alarba Magbanua (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Edzelle Inocencio Tubilla</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Nancy Loking Basa</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>Ma. Carmel Palabrica</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Roy Alarba Baling</b></li><li><b>Marlon Peladra Lademora</b></li><li><b>Armando Dologmanding Dapat</b></li><li><b>Romel Sombria Paclibar</b></li><li><b>Artemio Palmes Puig</b></li><li><b>Mauricio Precia Sombrea</b></li><li><b>Elvie Daza Tedios</b></li></ul></div>', 'Barangay Cubay, San Enrique, Iloilo', 'Cubay', '', '', 'https://www.facebook.com/profile.php?id=61556987704834', '11.08120345', '122.70823632', 'https://lh3.googleusercontent.com/d/16p_l5XHDQRgLeBocpotlsKBw9QtTgGLm', '[]', '', '', '', '', '10 km', '2,004', 'active', 0, 0, '0.00', '2026-03-22 14:09:14', '2026-05-24 14:41:56'),
(17, 2, 'Barangay Dacal', 'barangay-dacal', 'Is one of 28 barangays that make up the municipality within Western Visayas. Barangay Dacal had a population of 1,182. This made it the 16th largest of 28 barangays in San Enrique by population, placing it in the middle tier of the municipality. Residents of Barangay Dacal accounted for approximately 3.16% of the total population of San Enrique.<br><br>Local Products:<br><b>Sugarcane / Muscovado • Agricultural crops</b><br><br>Officials:<br><br>Punong Barangay<div><b>Garry Patrimonio Padre-e (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Mae Salcedo Labatagos</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Jennefer Ferrer Palmes</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>John Kenneth Agregado</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Chona Agregado Bugna</b></li><li><b>Jeric Oñada Duero</b></li><li><b>Jean Pamonag Collado</b></li><li><b>Cheryl Agregado Collado</b></li><li><b>Joemar Lara Celab</b></li><li><b>Ricky Pamplona Carte</b></li><li><b>Lea Padernilla Estelloro</b></li></ul></div>', 'Barangay Dacal, San Enrique, Iloilo', 'Dacal', '', '', 'https://www.facebook.com/profile.php?id=61556520538650', '11.11524601', '122.70374866', 'https://lh3.googleusercontent.com/d/1Wun5bHOp54-FshtemKzPIBwKCYzLGpPN', '[]', '', '', '', '', '7 km', '1,182', 'active', 0, 0, '0.00', '2026-03-22 14:09:14', '2026-05-24 14:41:56'),
(18, 2, 'Barangay Dumiles', 'barangay-dumiles', 'Barangay Dumiles is a small barangay in the municipality of San Enrique, located in the province of Iloilo, in the Western Visayas region of the Philippines. Barangay Dumiles had a population of 1,577. This made it the 10th largest of 28 barangays in San Enrique by population, placing it in the middle tier of the municipality. Residents of Barangay Dumiles accounted for approximately 4.22% of the total population of San Enrique. The simboryo in Barangay Dumiles stands as a humble yet meaningful structure that embodies the barangay&#039;s traditions and beliefs. Surrounded by nature, it creates a calm and reflective atmosphere for visitors. More than just a physical landmark, it symbolizes the enduring faith and cultural pride of the people of Dumiles.<br><br>Local Products:<br><b>Sugarcane / Muscovado • Dinulce nga kapayas (candied papaya) • Adobo nga langka (jackfruit) • Alupi • Cassava and camote products</b><br><br>Officials:<br><br>Punong Barangay<div><b>Maricar Palomo Orteguia (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Edna Palerit Namugot</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Sesa Pendon Chiva</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>Jhon Francis Dizon</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Estanislao Daborbor Dapat JR</b></li><li><b>Roland Tagulalap Dabordor</b></li><li><b>Jean Lapasaran Aposaga</b></li><li><b>Rodolfo Pallado Basio JR</b></li><li><b>Tommy Panerio Dabordor</b></li><li><b>Edin-eve Palomo Mercado</b></li></ul></div>', 'Barangay Dumiles, San Enrique, Iloilo', 'Dumiles', '', '', 'https://www.facebook.com/profile.php?id=100078247682899', '11.09997670', '122.70950057', 'https://lh3.googleusercontent.com/d/1o_C5K_rUgnf-vtS2Wnxq9ZEC_q1MTDtt', '[]', '', '', '', '', '11 km', '1,577', 'active', 0, 0, '0.00', '2026-03-22 14:09:14', '2026-05-24 14:41:56'),
(19, 2, 'Barangay Garita', 'barangay-garita', 'Classified as a mid-sized barangay, Barangay Garita is one of the administrative divisions of San Enrique in Iloilo, Western Visayas, Philippines. Barangay Garita had a population of 2,081. This made it the 3rd largest of 28 barangays in San Enrique by population, placing it among the most populous barangays of the municipality. Residents of Barangay Garita accounted for approximately 5.57% of the total population of San Enrique.<br><br>Local Products:<br><b>Milled rice • Corn • Root crops • Sugarcane / Muscovado</b><br><br>Officials:<br><br>Punong Barangay<div><b>Richard Palencia (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Gilmena Rapista</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Hardy Dumolong JR.</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>Mary Rose Palomar</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Tomas Eucos JR.</b></li><li><b>Leo Rapista</b></li><li><b>Lhuyen Gonzales SR.</b></li><li><b>Liza Palenca</b></li><li><b>Roberto Gonzales JR</b></li><li><b>Eduardo Villalobos</b></li><li><b>Daryl Agujetas</b></li></ul></div>', 'Barangay Garita, San Enrique, Iloilo', 'Garita', '', '', 'https://www.facebook.com/profile.php?id=61558183211226', '11.08169824', '122.73195189', 'https://lh3.googleusercontent.com/d/12ECATm1e-mea778IvXYjituXdkFowD3L', '[]', '', '', '', '', '4 km', '2,081', 'active', 0, 0, '0.00', '2026-03-22 14:09:14', '2026-05-24 14:41:56'),
