(29, 2, 'Barangay Poblacion Ilawod', 'barangay-poblacion-ilawod', 'Barangay Poblacion Ilawod is a small barangay in the municipality of San Enrique, located in the province of Iloilo, in the Western Visayas region of the Philippines. Barangay Poblacion Ilawod had a population of 1,612. This made it the 9th largest of 28 barangays in San Enrique by population, placing it in the upper half of the municipality. Residents of Barangay Poblacion Ilawod accounted for approximately 4.31% of the total population of San Enrique.<br><br>Local Products:<br><b>Milled rice • Corn • Root crops • Sugarcane / Muscovado • Kalamay (sticky rice cake)</b><br><br>Officials:<br><br>Punong Barangay<div><b>Noli Pamposa (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Maxielita Diala</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Glenda De La Peña</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>Carl Joseph Pamposa</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Ma. Neva Serbito</b></li><li><b>Julieta Panizales</b></li><li><b>Arturo Lallen JR</b></li><li><b>Matt Garbosa</b></li><li><b>Melvin Boyoging</b></li><li><b>Andy Panizales</b></li><li><b>Rudy Pamposa</b></li></ul></div>', 'Barangay Poblacion Ilawod, San Enrique, Iloilo', 'Poblacion Ilawod', '', '', 'https://www.facebook.com/profile.php?id=100086784212137', '11.06985974', '122.65527262', 'https://lh3.googleusercontent.com/d/14eBNpCB5GZhO59CfMyfH8UWes05mfrji', '[]', '', '', '', '', '1 km', '1,612', 'active', 0, 0, '0.00', '2026-03-22 14:09:14', '2026-05-24 14:41:56'),
(30, 2, 'Barangay Poblacion Ilaya', 'barangay-poblacion-ilaya', 'Classified as a small barangay, Barangay Poblacion Ilaya is one of the administrative divisions of San Enrique in Iloilo, Western Visayas, Philippines. Barangay Poblacion Ilaya had a population of 1,115. This made it the 17th largest of 28 barangays in San Enrique by population, placing it in the middle tier of the municipality. Residents of Barangay Poblacion Ilaya accounted for approximately 2.98% of the total population of San Enrique.<br><br>Local Products:<br><b>Milled rice • Corn • Root crops • Sugarcane / Muscovado • Kalamay (sticky rice cake)</b><br><br>Officials:<br><br>Punong Barangay<div><b>Vicente Pablico JR. (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Leah Penol</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Milrose Jamolangue</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>Ferdelmer Laurence Amora</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Felipe Paclibar</b></li><li><b>Jeffrey Prudente</b></li><li><b>Yolanda Prudente</b></li><li><b>Candelario Palabrica</b></li><li><b>Liezl Pulmones</b></li><li><b>Rene Penol</b></li><li><b>Clarence Lademora</b></li></ul></div>', 'Barangay Poblacion Ilaya, San Enrique, Iloilo', 'Poblacion Ilaya', '', '', 'https://www.facebook.com/SKPoblacionIlaya', '11.07534964', '122.65771193', 'https://lh3.googleusercontent.com/d/1FAnx_tnZd2RfibmDEaZ62BDzbwJMIPi6', '[]', '', '', '', '', '1 km', '1,115', 'active', 0, 0, '0.00', '2026-03-22 14:09:14', '2026-05-24 14:41:56'),
(31, 2, 'Barangay Quinolpan', 'barangay-quinolpan', 'Barangay Quinolpan forms part of San Enrique, a municipality in Iloilo, and is classified as a small barangay. Barangay Quinolpan had a population of 977. This made it the 21st largest of 28 barangays in San Enrique by population, placing it among the smaller barangays of the municipality. Residents of Barangay Quinolpan accounted for approximately 2.61% of the total population of San Enrique.<br><br>Local Products:<br><b>Sugarcane / Muscovado • Pineapple • Pineapple atsara (pickled relish)</b><br><br>Officials:<br><br>Punong Barangay<div><b>Camile Rose Pama (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Marry Mae Subaldo</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Delia Agravante Fernandez</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>Charlene Grace Panes</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Victor Malones</b></li><li><b>Cristina Bendoy Tumapang</b></li><li><b>Anecito Freires</b></li><li><b>Juliet Ballaran Relatos</b></li><li><b>Yen Rose Pagmanoja</b></li><li><b>Kevin Arzagon Panes</b></li><li><b>Meriam Agravante Fernandez</b></li></ul></div>', 'Barangay Quinolpan, San Enrique, Iloilo', 'Quinolpan', '', '', 'https://www.facebook.com/barangayquinolpansanenriqueiloilophilippines5036', '11.10277981', '122.69413118', 'https://lh3.googleusercontent.com/d/1c7tOTPS4E9rEm-XfA6vlnE8txmYMUOUk', '[]', '', '', '', '', '12 km', '977', 'active', 0, 0, '0.00', '2026-03-22 14:09:14', '2026-05-24 14:41:56'),
(32, 2, 'Barangay Rumagayray', 'barangay-rumagayray', 'Situated in San Enrique, Iloilo, Barangay Rumagayray is one of 28 barangays that make up the municipality within Western Visayas. Barangay Rumagayray had a population of 1,241. This made it the 15th largest of 28 barangays in San Enrique by population, placing it in the middle tier of the municipality. Residents of Barangay Rumagayray accounted for approximately 3.32% of the total population of San Enrique.<br><br>Local Products:<br><b>Sugarcane / Muscovado • Pineapple • Pineapple atsara (pickled relish)</b><br><br>Officials:<br><br>Punong Barangay<div><b>Antonio Dato-on Lapastora JR. (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Kerr Belandres Lara</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Jose Richel Bolivar Lapastora</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>Shynah Shune Lapastora</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Danilo Pacaco Borda</b></li><li><b>Harry Pacaco Palma</b></li><li><b>Wilbert Lapastora Paclibar</b></li><li><b>Rose Eden Lara Bayombong</b></li><li><b>Rodel Daras</b></li><li><b>Resty Castor Lara</b></li><li><b>Zaldy Lapastora</b></li></ul></div>', 'Barangay Rumagayray, San Enrique, Iloilo', 'Rumagayray', '', '', 'https://www.facebook.com/groups/1556000491533439', '11.04405158', '122.64825408', 'https://lh3.googleusercontent.com/d/1YlOJhb_Bjxz5kkini2N6gwz-bNnQ1-qk', '[]', '', '', '', '', '11 km', '1,241', 'active', 0, 0, '0.00', '2026-03-22 14:09:14', '2026-05-24 14:41:56'),
(33, 2, 'Barangay San Antonio', 'barangay-san-antonio', 'Barangay San Antonio is a small barangay in the municipality of San Enrique, located in the province of Iloilo, in the Western Visayas region of the Philippines. Barangay San Antonio had a population of 575. This made it the 25th largest of 28 barangays in San Enrique by population, placing it among the smaller barangays of the municipality. Residents of Barangay San Antonio accounted for approximately 1.54% of the total population of San Enrique.<br><br>Local Products:<br><b>Sugarcane / Muscovado • Poultry and swine • Vermicompost / organic products</b><br><br>Officials:<br><br>Punong Barangay<div><b>Cezar Biñas (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Sherlyn Lagradante</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Joy Mae Aguilar Villaret</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>Jhon Ryan Balume</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Joseph Esmille</b></li><li><b>Lea Edong Alada</b></li><li><b>Leonardo Ordejan Agulay</b></li><li><b>Joemarie Agtas Alada</b></li><li><b>Susette Alada</b></li><li><b>Enrique Espinosa JR.</b></li><li><b>Rey Pagmanoja</b></li></ul></div>', 'Barangay San Antonio, San Enrique, Iloilo', 'San Antonio', '', '', '', '11.12558098', '122.77806342', 'https://lh3.googleusercontent.com/d/1C0hnFiOzU68wVntr2L4SGUzLyM4I3yyR', '[]', '', '', '', '', '5 km', '575', 'active', 0, 0, '0.00', '2026-03-22 14:09:14', '2026-05-24 14:41:56'),
(34, 2, 'Barangay Tambunac', 'barangay-tambunac', 'Classified as a small barangay, Barangay Tambunac is one of the administrative divisions of San Enrique in Iloilo, Western Visayas, Philippines. Barangay Tambunac had a population of 735. This made it the 24th largest of 28 barangays in San Enrique by population, placing it among the smaller barangays of the municipality. Residents of Barangay Tambunac accounted for approximately 1.97% of the total population of San Enrique.<br><br>Local Products:<br><b>Sugarcane / Muscovado • Poultry and swine • Vermicompost / organic products</b><br><br>Officials:<br><br>Punong Barangay<div><b>Rubirosa Pabilona (2023 - 2026 term)</b></div><div><b><br></b></div><div>Barangay Secretary</div><div><b>Andres Siaotong JR.</b></div><div><b><br></b></div><div>Barangay Treasurer</div><div><b>Jenelyn Castillo</b></div><div><b><br></b></div><div>SK Chairperson</div><div><b>Lissca Padernal</b></div><div><b><br></b></div><div>Sangguniang Barangay Members (Kagawads)</div><div><ul><li><b>Rene Paclibar</b></li><li><b>Argie Lozada</b></li><li><b>Rocky Jagunap</b></li><li><b>Analyn Girao</b></li><li><b>Jeffrey Palermo</b></li><li><b>Gerald Palermo</b></li><li><b>Den Mark Silvestre</b></li></ul></div>', 'Barangay Tambunac, San Enrique, Iloilo', 'Tambunac', '', '', 'https://www.facebook.com/barangay.tambunac', '11.07454366', '122.68047106', 'https://lh3.googleusercontent.com/d/1y4KKL1il7H8HWNBtJfrzgu2ZMYHRgR2s', '[]', '', '', '', '', '13 km', '735', 'active', 0, 0, '0.00', '2026-03-22 14:09:14', '2026-05-24 14:41:56'),
(35, 5, 'Gumbans Amat Amat Farm', 'gumbans-amat-amat-farm', 'Gumbans Amat Amat Farm is a peaceful farm offering fresh produce and scenic views. Enjoy their fruit trees, fish pond, and vegetable garden. Enjoyable views include fruit trees (peach, lemon, avocado, coconut), fish pond, and vegetable garden.', 'Sitio Gelonoc Cubay, San Enrique, Iloilo', 'Cubay', '09627603707 / 09455067648', '', 'https://www.facebook.com/share1DHRHN9kbMn/?mibextid=wwXlfr', '11.07570800', '122.71619900', 'https://lh3.googleusercontent.com/d/1uaYxkPouG_dWftb9hcdaFfrhSLojdKLG', '[\"https:\\/\\/drive.google.com\\/thumbnail?id=1IW48uk2mMRw_V9t1GBlAJFZ2sqK734yr&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1t3SUhrRtzoDgU0LhzJ01e6guYK1vsH9j&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=10DbRpy4JVFF2pK1nam8yPp1all38hrCr&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1GkZTMhPzaJjA_Hb9jxcRTq4XhFYRQgFe&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1zKo-gTVb_LudmmV6zwsz-sTLuQmX8UWT&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=16xFi86vZSSb_jojTIQmSBc5XLZhUVJ9n&sz=w1200\"]', '', 'Monday to Friday: 8:00 AM - 5:00 PM; Saturday and Sunday: 9:00 AM - 5:00 PM', 'Contact for rates', 'Fruit trees (peach, lemon, avocado, coconut), Fish pond, Vegetable garden', NULL, NULL, 'active', 0, 22, '0.00', '2026-03-22 14:09:14', '2026-03-31 03:58:00'),
(36, 1, 'Cabas-an Cold Spring', 'cabas-an-cold-spring', 'Cabasan Cold Spring is a natural spring offering cool, clear waters perfect for swimming and relaxation. Enjoyable views include lush greenery, natural rock formations, and scenic surroundings. Activities: swimming, picnic, and nature walks.', 'Sitio Cabas-an, Brgy. Compo, San Enrique, Iloilo 5036', 'Compo', '0917 302 3878', 'ebtconfi2@gmail.com', 'https://facebook.com/composanenriqueiloilo', '10.91780000', '122.88450000', 'https://lh3.googleusercontent.com/d/1IIzqR-BdAVla0bMmoQVD6O4b2L7e-74G', '[\"https:\\/\\/lh3.googleusercontent.com\\/d\\/12_pjtS1JzfpboXJGEyNQKp2DR7pRNsY5\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1ojNuVohcmWTDIHtfh-IF8hGNbNUGEAxU\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1qma6CERcakkjnLlFdzkVojHpWaxVK-8C\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1abm-slqtPqTsznRa1AFP5KdU8xJRX-w8\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1BDLkortHSboFCsq4CWV1Y5nyrH064tYc\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1RWfwKrgR61EV0USFDUrydHelQK1mo3-D\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1BLgm5FehwbCIyzO5Vri68G0DWSY61LYI\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1EtwrlQ4A-WW4jMiCuN5OVGKymORAMK_R\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1cF3dMUHLpp9DRIgxk_9uVEw6X1zXxoTV\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1IIzqR-BdAVla0bMmoQVD6O4b2L7e-74G\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1xRD3avFozrLY68iax2PEMOfTBzInihdp\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1N_lIjMkZuqMjPx5JMYhqqqQwYqAaKaiU\"]', '', '7:00 AM - 5:00 PM, Daily', 'Contact for rates', 'Natural spring pool, Swimming area, Picnic area, Nature walks, Rock formations', NULL, NULL, 'active', 1, 17, '0.00', '2026-03-22 21:09:14', '2026-05-25 07:19:09'),
(37, 5, 'BC Farm', 'bc-farm', 'BC Farm is a peaceful farm in San Enrique, Iloilo, offering a serene atmosphere for swimming and relaxation.', 'Brgy Cabugao Viejo, San Enrique, Iloilo 5036', 'Cabugao Viejo', '0985 181 9131', 'benedictopadon@gmail.com', 'https://facebook.com/BCResortSanEnrique', NULL, NULL, NULL, NULL, '', 'Daily (open 24/7)', 'Contact for rates', 'Swimming area, Farm atmosphere, Relaxation area', NULL, NULL, 'active', 0, 2, '0.00', '2026-03-22 21:09:14', '2026-05-25 06:38:14'),
(38, 5, 'Tonys Farm Resort', 'tonys-farm-resort', 'Tonys Valley Farm Resort is a private resort offering a peaceful atmosphere with swimming pools and cottages. Enjoyable views include lush greenery, swimming pools, and scenic surroundings. Activities: swimming, picnic, and nature walks.', 'Sitio Layog Bato, Brgy. Mapili, San Enrique, Iloilo', 'Mapili', '0908 866 6909', '', 'https://facebook.com/TVFRM', '11.10524189', '122.74732590', 'https://lh3.googleusercontent.com/d/1im3ZlRXO7ii_KD2BSfv06e6M9FJOe94J', '[\"https:\\/\\/drive.google.com\\/thumbnail?id=117MzqUHHBuOSq0_xkM_EJn_B8tpRNqGr&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=15AU4AYUXkLrSYhcjy4OR5JPYSTJHaSCY&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1rMd2jA-BPZJp3Hw9wbxkoJL8T6fX6Ikv&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1ZSuQsVMts2dwPTtJqsPsoe0j1M0dx0ph&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1mmblj7BmZVrhqkaWVo7SdOEV5yIJkRqu&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1tUD02J6Ln8sRFatJjqoId-PYUJwTsrNp&sz=w1200\"]', '', 'Daily (contact for specific hours)', 'Contact for rates', 'Swimming pools, Cottages, Picnic area, Nature walks, Lush greenery', NULL, NULL, 'active', 1, 19, '0.00', '2026-03-22 14:09:14', '2026-03-31 01:25:32');
