(39, 6, 'San Antonio San Enrique River', 'san-antonio-san-enrique-river', '<p>The San Antonio San Enrique River offers a serene spot for nature lovers, fishing, and relaxation. Enjoy the scenic views and tranquility. Activities: fishing, swimming, picnic, and nature walks.</p>', 'San Antonio, San Enrique, Iloilo', 'San Antonio', '', '', '', '11.13103180', '122.76720200', 'https://lh3.googleusercontent.com/d/1Tk9xlfh6LCo7blrbYy4gwwEREKVHH4Xp', '[]', '', '24/7 (river access); Best time to visit: 6:00 AM - 5:00 PM', '', 'Fishing, Swimming, Picnic area, Nature walks, Scenic river views', '', '', 'active', 0, 1, '0.00', '2026-03-22 14:09:14', '2026-05-25 01:48:20'),
(40, 6, 'Catan-Agan San Enrique River', 'catan-agan-san-enrique-river', '<p>The Catan-Agan San Enrique River offers a serene spot for nature lovers, fishing, and relaxation. Enjoy the scenic views and tranquility. Activities: fishing, swimming, picnic, and nature walks.</p>', 'Catan-Agan, San Enrique, Iloilo', 'Catan-Agan', '', '', '', '11.12440940', '122.74875966', 'https://lh3.googleusercontent.com/d/1xJwMrLWubZyLyFkRMj0GAtVPGkeeFShZ', '[\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1J0SUIT63FziBoAcCNzFbzqWji-wUJOja\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1wA_xLS_DGhGMQ0_hWUAvUovXAwc3FXO7\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/13Jq62X_UhiYG2genjcl-QvpfvnfEfFwp\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/13eld7kjD7OlTpsd0bjIWpY0l4NLaq08W\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1dlMdr8MkLoHmAwZbm2djfejCyKe_zkqR\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1LWJvKKjzIoIC-M6FmIBIIuNZbq5SVucn\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1lxLoslb7z6EMSkeTbkUI_tYC3V1dEoLp\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1zzf_30KnT3uLs_sF-Bf3VFzMnjVkaVzo\"]', '', '24/7 (river access); Best time to visit: 6:00 AM - 5:00 PM', '', 'Fishing, Swimming, Picnic area, Nature walks, Scenic river views', '', '', 'active', 1, 8, '0.00', '2026-03-22 14:09:14', '2026-05-25 07:25:10'),
(41, 4, 'Puto (Native Delicacy)', 'puto-native-delicacy', 'A famous Filipino steamed rice cake. In San Enrique, Puto is traditionally sold by vendors outside the church or inside the market, especially after Sunday Mass. Best prepared and paired with Dinuguan.', 'Local Markets &amp;amp; Church Vicinity, San Enrique, Iloilo', 'Poblacion', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1jH7vN_zU30GU9JKkb8fwUXFfWHN9OpNW&sz=w1200', '[]', '', 'Sundays (after Mass) and daily in local markets', 'Market price', '', NULL, NULL, 'active', 0, 1, '0.00', '2026-03-22 14:09:14', '2026-03-30 15:30:20'),
(42, 4, 'Kutsinta (Native Delicacy)', 'kutsinta-native-delicacy', 'A popular steamed rice cake in San Enrique, Iloilo, often featured alongside the town&amp;#039;s famous kalamay as a staple &amp;quot;pang yam-is&amp;quot; (sweet) merienda. These sticky, chewy, and brown or black treats are typically served with freshly grated coconut. Made from all-purpose flour or tapioca starch, brown sugar, lye water, and annatto water, steamed for 30-45 minutes.', 'Local Markets, San Enrique, Iloilo', 'Poblacion', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=17J3QnUoyYyECtfZ5VE1suFQS6IagDivD&sz=w1200', '[]', '', 'Daily in local markets', 'Market price', '', NULL, NULL, 'active', 0, 0, '0.00', '2026-03-22 14:09:14', '2026-03-30 06:56:51'),
(44, 4, 'Inday-Inday (Native Delicacy)', 'inday-inday-native-delicacy', 'A traditional Ilonggo native delicacy (kakanin) popular in San Enrique, Iloilo, and other parts of Western Visayas. A sweet, chewy snack made from poached glutinous rice dough discs, very similar to palitaw, but distinguished by its rich, caramelized coconut topping known as bukayo.', 'Local Markets, San Enrique, Iloilo', 'Poblacion', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1TOU_rvuLRthmSFocbGTWHrL_dxqgV1d1&sz=w1200', '[\"https:\\/\\/drive.google.com\\/thumbnail?id=1EVc-KD8VjvmZP7Sfjtk1ldJl1VBvO5M0&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1EVc-KD8VjvmZP7Sfjtk1ldJl1VBvO5M0&sz=w1200\"]', '', 'Daily in local markets', 'Market price', '', NULL, NULL, 'active', 0, 0, '0.00', '2026-03-22 14:09:14', '2026-03-25 07:38:04'),
(45, 4, 'Kalamay Hati (Native Delicacy)', 'kalamay-hati-native-delicacy', 'A traditional Filipino sweet rice cake and a celebrated product of San Enrique, Iloilo, featured during their annual town festival. A very sticky, thick, and chewy delicacy made from ground glutinous rice, coconut milk, and muscovado or brown sugar, commonly topped with latik (coconut milk curds).', 'Local Markets, San Enrique, Iloilo', 'Poblacion', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1KLxBcaDEH2fwunVmusM6VA-867FWxM7u&sz=w1200', '[]', '', 'Daily in local markets', 'Market price', '', NULL, NULL, 'active', 0, 6, '0.00', '2026-03-22 14:09:14', '2026-03-31 04:41:47'),
(46, 4, 'Minatamis na Saging (Native Delicacy)', 'minatamis-na-saging-native-delicacy', 'A staple Filipino dessert and merienda popular throughout Iloilo, including San Enrique, often served as a simple treat, a topping for shaved ice (Saba con Yelo), or an ingredient in halo-halo. Consists of ripe Saba bananas simmered until tender in a thickened, caramelized brown sugar syrup, sometimes enhanced with pandan leaves, vanilla, or salt to balance the sweetness.', 'Local Markets, San Enrique, Iloilo', 'Poblacion', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1eISy9Y_I5cIfWa2zpcca8ydUfKDZP-rM&sz=w1200', '[]', '', 'Daily in local markets', 'Market price', '', NULL, NULL, 'active', 0, 1, '0.00', '2026-03-22 14:09:14', '2026-03-28 10:39:14'),
(47, 4, 'Suman (Native Delicacy)', 'suman-native-delicacy', 'A popular native delicacy (kakanin) in San Enrique, Iloilo, known for its deep brown color, sticky texture, and rich flavor. A traditional Ilonggo suman typically wrapped in banana leaves and may come topped with latik (coconut caramel) or served plain, often prepared by local makers, including seniors who have learned the traditional process.', 'Local Markets, San Enrique, Iloilo', 'Poblacion', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1yBmYj08lx8xmUUdC6BRpqT1eh7sm9dYU&sz=w1200', '[]', '', 'Daily in local markets', 'Market price', '', NULL, NULL, 'active', 0, 1, '0.00', '2026-03-22 14:09:14', '2026-03-27 06:27:10'),
(48, 4, 'Bibingka (Native Delicacy)', 'bibingka-native-delicacy', 'A traditional, soft, and slightly sweet rice cake from San Enrique, Iloilo, cooked over live charcoal in banana leaf-lined molds. Known for its aromatic aroma, this native delicacy is typically made from rice flour (or soaked glutinous rice), coconut milk, sugar, eggs, and topped with cheese, salted eggs, or shredded coconut.', 'Local Markets, San Enrique, Iloilo', 'Poblacion', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1gKuDXlDY0w4hpgXyh75YX-YD_--3Lcx7&sz=w1200', '[]', '', 'Daily in local markets', 'Market price', '', NULL, NULL, 'active', 0, 1, '0.00', '2026-03-22 14:09:14', '2026-03-28 10:39:51'),
(49, 4, 'Baye-Baye (Native Delicacy)', 'baye-baye-native-delicacy', 'A popular native delicacy in San Enrique, from Barangay Poblacion Ilawod. A well-loved San Enriquenhon treat made from grounded corn, sugar, and coconut. It is always served during Pista Mais Festival of the said barangay, every month of August.', 'Local Markets, San Enrique, Iloilo', 'Poblacion Ilawod', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1FThaPXvB-Wc0Uy5gPT2d65nuUwX-WtH3&sz=w1200', '[]', '', 'For order.', '150/Tub', '', NULL, NULL, 'active', 0, 3, '0.00', '2026-03-22 14:09:14', '2026-03-27 06:34:40'),
(50, 4, 'Muasi (Native Delicacy)', 'muasi-native-delicacy', 'A popular, traditional Ilonggo delicacy often found in San Enrique and throughout Iloilo. Recognized as an Ilonggo version of palitaw, consisting of soft, chewy dumplings made from glutinous rice, commonly topped or stuffed with toasted sesame seeds and sugar.', 'Local Markets, San Enrique, Iloilo', 'Poblacion', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1y7nWn87p3mghZz-y7Mo-Xb1HzdLuqDED&sz=w1200', '[]', '', 'Daily in local markets', 'Market price', '', NULL, NULL, 'active', 0, 0, '0.00', '2026-03-22 14:09:14', '2026-03-25 07:16:42'),
(51, 4, 'Ibos / Dali-Dalin (Native Delicacy)', 'ibos-dali-dalin-native-delicacy', 'A type of sticky rice (glutinous rice) wrapped in coconut or buri leaves, popularly called Ibos. Best enjoyed dipped in sugar.', 'Local Markets, San Enrique, Iloilo', 'Poblacion', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1kOAVK3hqL4bt9CjgD8-epGvS9ZyVofVj&sz=w1200', '[]', '', 'Daily in local markets', 'Market price', '', NULL, NULL, 'active', 0, 0, '0.00', '2026-03-22 14:09:14', '2026-03-25 07:17:13'),
(52, 3, 'Simboryo ng Barangay Quinolpan', 'simboryo-ng-barangay-quinolpan', '<p>The simboryo in Barangay Quinolpan stands as a peaceful landmark that reflects the barangay&amp;#039;s deep spiritual roots and close-knit community. Modest yet meaningful, it serves as a place where locals gather for quiet prayer and reflection. Surrounded by open fields and fresh air, the simboryo mirrors the simplicity and strong faith of the people, preserving their traditions through time.</p>', 'Barangay Quinolpan, San Enrique, Iloilo', 'Quinolpan', '', '', '', '11.10297512', '122.69392528', 'https://drive.google.com/thumbnail?id=1FpAWhG3yeYO7oQm1V-uVZqvvFdVkP08l&sz=w1200', '[\"https:\\/\\/drive.google.com\\/thumbnail?id=1jN5d0BuRelOoNFQ38wKmn6pfbMA8Fk9b&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1SyZeW4Pl9OgLFGHUFlCCW4FqZATHfJuQ&sz=w1200\"]', '', 'Open daily', '', '', '', '', 'active', 0, 0, '0.00', '2026-03-22 14:09:14', '2026-05-25 01:39:54'),
(53, 3, 'Simboryo ng Barangay Cubay', 'simboryo-ng-barangay-cubay', '<p>In Barangay Cubay, the simboryo rises as a symbol of unity and devotion. Its aged structure tells stories of shared beliefs and generations who have kept their faith alive. Often visited during moments of need or gratitude, it remains a sacred space that connects the past with the present, reminding the community of their enduring cultural identity.</p>', 'Barangay Cubay, San Enrique, Iloilo', 'Cubay', '', '', '', '11.08164679', '122.70841494', 'https://drive.google.com/thumbnail?id=19JMq4NNApJIL5niytnOnVLKWJq9MH_lL&sz=w1200', '[\"https:\\/\\/drive.google.com\\/thumbnail?id=1efwZ-NxzPxk1Sjw5C17ZnkEfzFGHGsMw&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1o0aBDwIZdqaYSjfWBGbn4FAY1kZEWJCn&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1jA-pv1qPg8Yrmn_ncS_knJpLh2giExNc&sz=w1200\"]', '', 'Open daily', '', '', '', '', 'active', 0, 1, '0.00', '2026-03-22 14:09:14', '2026-05-25 01:40:13'),
(54, 3, 'Simboryo ng Barangay Camiri', 'simboryo-ng-barangay-camiri', '<p>The simboryo of Barangay Camiri is a quiet yet striking reminder of the barangay\'s cultural heritage. Nestled within a serene environment, it stands as a witness to the passing of time and the resilience of local traditions. Its presence brings a sense of peace and continuity, reflecting the community\'s strong spiritual connection and respect for their history. And it is the most intact of all the simboryo on the list</p>', 'Barangay Camiri, San Enrique, Iloilo', 'Camiri', '', '', '', '11.08163314', '122.65216343', 'https://drive.google.com/thumbnail?id=1t-8OrfAJ6TSZDiuMHbjt8QszELTvDB4X&sz=w1200', '[\"https:\\/\\/drive.google.com\\/thumbnail?id=1Tr8OcKIfNy_R--9J1jDRK6pBi8szrZYV&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1P9khlHiddAQx4COuzuLPsWUDe0PqrFfg&sz=w1200\"]', '', 'Open daily', '', '', '', '', 'active', 0, 2, '0.00', '2026-03-22 14:09:14', '2026-05-25 01:39:39'),
(56, 3, 'Simboryo ng Barangay Dumiles', 'simboryo-ng-barangay-dumiles', '<p>The simboryo in Barangay Dumiles stands as a humble yet meaningful structure that embodies the barangays traditions and beliefs. Surrounded by nature, it creates a calm and reflective atmosphere for visitors. More than just a physical landmark, it symbolizes the enduring faith and cultural pride of the people of Dumiles.</p>', 'Barangay Dumiles, San Enrique, Iloilo', 'Dumiles', '', '', '', '11.09951713', '122.70926029', 'https://lh3.googleusercontent.com/d/1PvwMc6fi8j2Y6KGqkTrtOVT4JP1soIcz', '[]', '', 'Open daily', '', '', '', '', 'active', 0, 3, '0.00', '2026-03-22 14:09:14', '2026-05-25 01:47:22'),
(57, 6, 'Mt. Bayuso', 'mt-bayuso', 'Mount Bayuso is one of San Enrique’s hidden natural treasures, offering a refreshing escape for nature lovers and adventure seekers. Known for its lush greenery and scenic views, the mountain provides a perfect spot for hiking and outdoor exploration. At the summit, visitors are rewarded with breathtaking landscapes that showcase the beauty of the town and its surroundings. It represents the untouched and serene side of San Enrique, promoting eco-tourism and appreciation for nature.', '', 'Abaca', '', '', '', '11.13060000', '122.72810000', 'https://lh3.googleusercontent.com/d/1YF7ejJvzeh4qCoaENAxzpm_bVO8AiGq4', '[]', '', '', '', '', NULL, NULL, 'active', 1, 0, '0.00', '2026-03-22 15:07:06', '2026-03-31 03:58:24'),
(58, 6, 'Hacienda Pavilion', 'hacienda-pavilion', 'The Hacienda Pavilion is a charming venue in San Enrique that blends rustic elegance with the peaceful ambiance of the countryside. Surrounded by natural scenery, it serves as a perfect location for g\\\\r\\\\natherings, celebrations, and tourism activities. Its open-air design and spacious setting make it ideal for weddings, events, and community programs. The pavilion reflects the town’s appreciation for simple yet beautiful spaces where people can connect, celebrate, and enjoy nature.', '', 'Dumiles', '', '', '', '11.10057700', '122.70732800', 'https://lh3.googleusercontent.com/d/1C_ifiPtcKIpAusFxksj3Jqk_2vPC8deq', '[]', '', '', '', '', NULL, NULL, 'active', 0, 1, '0.00', '2026-03-22 15:08:52', '2026-03-31 06:45:56'),
(60, 3, 'Artifacts', 'artifacts', 'The collection of artifacts in San Enrique showcases the rich cultural heritage and everyday life of the past generations. Each item tells a unique story about tradition, livelihood, and history:', '', '', '', '', '', '11.07215485', '122.65655483', 'https://lh3.googleusercontent.com/d/1ANSA1C7-BiNJFVMPiB5s_C8x4wrW8IUb', '[\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1XZ-EbThSle2mcch4X4EXRoYmRZU_2OUg\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1jBrj0uKTS-aEhmu7fxUFXzdTXKX-KZ4w\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1USxwn50H_QCT75WbbnCYpRIZAWOgo8Am\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1a4Jq_M4NCrtZ-lpKB_aRE9O-PC-RZZo8\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/1BJeaohmcVtQvPKb7y0mtjtoGrZCWN_qc\",\"https:\\/\\/lh3.googleusercontent.com\\/d\\/15rPqGEse4Xroy4UgbFUTLOKbgvNeGfdj\"]', '', '', '', '', NULL, NULL, 'active', 0, 16, '0.00', '2026-03-22 15:26:55', '2026-05-25 06:14:09'),
(61, 4, 'Linugaw Nga Pilit', 'linugaw-nga-pilit', 'It is one of the native sweet delicacy in San Enrique, usually being prepared during birthdays and other occasions in the highlands. It is made from glutenous rice, coconut milk, ripe jackfruit, with different root crops.', 'Anywhere in the Municipality', 'Poblacion', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1VgQnQ_te9_IY_KpcnjXoJ9Eb6NhdllEI&sz=w1200', '[]', '', 'Sundays for local market day', 'Market price', '', NULL, NULL, 'active', 0, 2, '0.00', '2026-03-27 06:38:49', '2026-03-31 02:16:24'),
(62, 4, 'Banana and Cassava Cake', 'banana-and-cassava-cake', 'Another sweet delicacy from the municipality, made from cassava roots, and ripe banana.', 'Poblacion Ilaya, beside Municipal Plaza', 'Poblacion Ilaya', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1gA0sSk3mj8tKNva_KaOZXQM8nSApPh8B&sz=w1200', '[\"https:\\/\\/scontent.fceb1-3.fna.fbcdn.net\\/v\\/t39.30808-6\\/657265589_122105553921072244_2729049142381042487_n.jpg?_nc_cat=106&ccb=1-7&_nc_sid=13d280&_nc_eui2=AeEtwH0w6-3e9WL7OQlp2ipgE_x_1pYAlvUT_H_WlgCW9Sd6t4ltnS9ENNNjqZQ2pWJaa4AGEyJDAkEGd1NPMvSJ&_nc_ohc=eU5CobTN0BwQ7kNvwFO7Hjz&_nc_oc=AdoTzyEJTUPXbbYJy7WdDI2erTk4jj9vzrjdExhqxlO3_a1Sv3KFFmlqaZANho3FF0R3ZDbLP8t2Xa2L4TirLCSG&_nc_zt=23&_nc_ht=scontent.fceb1-3.fna&_nc_gid=dRO1gjQsFDgKryUAe_F7Cg&_nc_ss=7a3a8&oh=00_AfwbD8zmR2phAEeiLUIuRnVa3tc-P-yIt9uZlD7f84GEFw&oe=69D03F7B\"]', '', 'For order.', '400/Tub', '', NULL, NULL, 'active', 0, 5, '0.00', '2026-03-27 06:42:55', '2026-05-25 06:03:21'),
(63, 3, 'Simboryo  ng Barangay Paga', 'simboryo-ng-barangay-paga', 'The simboryo in Barangay Paga stands as a quiet yet powerful symbol of the rich heritage of San Enrique. This old structure, weathered by time, reflects the deep-rooted traditions and spiritual life of the community. Often built as a small stone chapel or shrine, the simboryo represents the strong faith and unity of the people, serving as a place for prayer, reflection, and remembrance.\r\n\r\nSurrounded by natural landscape, it blends history with nature—its aged walls telling stories of generations past. More than just an architectural feature, the simboryo embodies the identity of San Enrique, preserving its culture, beliefs, and enduring connection to its history.', '', 'Paga', '', '', '', '11.08551734', '122.67053767', 'https://drive.google.com/thumbnail?id=1dmvT472c05Q-uoZ3-oH2lvhotMoz9CRT&sz=w1200', '[\"https:\\/\\/drive.google.com\\/thumbnail?id=1qiQViMSGw454VoNxLNfrv2E8_c2HBxdY&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1rSdFzKmn4Bg8xmfPlOKBCWRJ-xKORxCH&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1DwknLMEFkABdWTxEj9h_6i0cZyT9EQAI&sz=w1200\"]', '', '', '', '', NULL, NULL, 'active', 0, 4, '0.00', '2026-03-30 14:00:11', '2026-05-25 01:38:29'),
(65, 1, 'Tonys Farm Resort', 'tonys-farm-resort-1', 'Tonys Valley Farm Resort is a private resort offering a peaceful atmosphere with swimming pools and cottages. Enjoyable views include lush greenery, swimming pools, and scenic surroundings. Activities: swimming, picnic, and nature walks.', '', 'Mapili', '0908 866 6909', '', '', '11.10524189', '122.74732590', 'https://drive.google.com/thumbnail?id=1rMd2jA-BPZJp3Hw9wbxkoJL8T6fX6Ikv&sz=w1200', '[\"https:\\/\\/drive.google.com\\/thumbnail?id=1sB6fes7Q_O4NJZtGuOb_V7Wa10fsEbik&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=117MzqUHHBuOSq0_xkM_EJn_B8tpRNqGr&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=12jYDEdFRi98wjeVq5vRUuvDC7OVa7TFg&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=15AU4AYUXkLrSYhcjy4OR5JPYSTJHaSCY&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1WVCNkOguBEd_pxrCWF0K9OAhG2jEzfFl&sz=w1200\"]', '', 'Daily (contact for specific hours)', 'Contact for rates', '', NULL, NULL, 'active', 0, 4, '0.00', '2026-03-31 01:29:58', '2026-05-25 07:20:36'),
(67, 3, 'Artifact-Plantsa de uling', 'artifact-plantsa-de-uling', 'These antique items are traditional charcoal-heated irons, often referred to in the Philippines as plantsa de uling. \r\nThey feature heavy cast iron bodies designed to hold live coals for heat. \r\nThe handles are typically made of wood, and some models include decorative elements like a rooster on top. \r\nThese irons are popular collectible items representing a pre-electric era of laundry care. \r\nThey are still sought after for decorative purposes or for their sustainable, non-electric functionality.', '', '', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1OJfYBGT4fdgOCWcsIB3fQMNMUu_UjpwB&sz=w1200', '[]', '', '', '', '', NULL, NULL, 'active', 0, 0, '0.00', '2026-04-12 01:31:55', '2026-04-12 01:31:55'),
(68, 3, 'Artifact- Kingki', 'artifact-kingki', 'Kingki, a vintage kerosene lamp commonly used in the past for lighting before electricity became widely available. The Kingki has a sturdy black metal frame with a clear glass chamber in the center that protects the flame from wind. A small handle on top makes it easy to carry, while the base holds the fuel that powers the lamp.\r\nSeveral Kingki lamps are neatly displayed on a table, suggesting they are part of a historical or cultural exhibit. Behind them, other old objects and memorabilia can be seen, adding to the antique atmosphere. These lamps represent simple yet practical lighting tools used in homes, especially in rural areas, during nighttime or power outages.In addition, the Kingki symbolizes traditional living, resourcefulness, and the history of early household lighting.', '', '', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=18BurI6evtTHSXEgYCg6aYWVnz_Ol9UNG&sz=w1200', '[]', '', '', '', '', NULL, NULL, 'active', 0, 3, '0.00', '2026-04-12 01:56:30', '2026-04-17 00:12:11'),
(69, 3, 'Artifact-Raynahan', 'artifact-raynahan', 'The Raynahan is a traditional wooden container used in the past for storing rice and other grains. It is usually made from thick, durable wood and shaped like a rectangular box with sturdy sides. The surface often looks rough and aged because it was commonly used in homes and farms for many years.\r\nThis particular Raynahan appears old and weathered, showing signs of long-term use. The wood has cracks and worn edges, which suggest it was handcrafted and repeatedly handled. Its deep interior allowed people to store harvested rice safely, keeping it dry and protected from pests.\r\nRaynahan reflects traditional Filipino farming practices, where families stored their rice supply after harvest. It symbolizes self-sufficiency, hard work, and the importance of agriculture in rural communities.', '', '', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=10ad6t3mZH1nrJZRnebX89FNh9wkPbbhM&sz=w1200', '[]', '', '', '', '', NULL, NULL, 'active', 0, 0, '0.00', '2026-04-12 06:50:32', '2026-04-12 06:50:32'),
(70, 3, 'Artifact-Garapon', 'artifact-garapon', 'The Garapon is large glass jars and bottles traditionally used for storing liquids and food items. These containers come in different shapes and colors, including clear, green, and brown glass. They are wide-mouthed, making them easy to fill, clean, and reuse.\r\nIn the past, garapons were commonly used in households to store water, vinegar, oil, local beverages, or preserved foods. The thick glass material helped keep the contents safe and fresh. Some were also used in small stores for selling products in bulk.\r\nThe arrangement of multiple garapons on display suggests they are part of a cultural or historical exhibit, highlighting everyday storage tools used before modern plastic containers became popular. Overall, the garapon represents practicality, sustainability, and traditional Filipino household practices.', '', '', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1BcgcAd9mt_WUDutuCOnKF_gE9JZM7WwY&sz=w1200', '[]', '', '', '', '', NULL, NULL, 'active', 0, 0, '0.00', '2026-04-12 06:51:24', '2026-04-12 06:51:24'),
(71, 3, 'Artifact-Alkansiya', 'artifact-alkansiya', 'Alkansiya is a humble yet powerful symbol of Ilonggo &amp;quot;pinaagi&amp;quot; (resourcefulness).\r\n​Handcrafted from local earthenware, its rugged, cross-hatched surface reflects the traditional pottery techniques of the region. For generations in San Enrique, these clay jars were essential household tools used to cultivate the habit of diniyut (saving bit by bit).\r\n​Often filled with coins from local trade or harvests, the jar would eventually be broken to fund a childs education or a family milestone. Today, displayed as a preserved artifact, it stands as a tribute to the town’s values of thrift, hard work, and preparation for the future.', '', '', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1xEM_9EOw5ZrAH1ZryukKd_UetxdC_j1_&sz=w1200', '[]', '', '', '', '', NULL, NULL, 'active', 0, 0, '0.00', '2026-04-12 07:27:03', '2026-04-17 01:12:28'),
(72, 3, 'Artifact- Espading', 'artifact-espading', '​Espading: This is a traditional long-bladed tool, similar to a machete but with a distinct straight edge. In San Enrique, it is the primary tool of the sacada (sugar worker), used with precision to cut and clean sugarcane stalks during the harvest season. It symbolizes the strength and endurance of the local laborers.', '', '', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1QM6OOkreEm8UtMUkOU6nJ5f_4N-qdXRz&sz=w1200', '[]', '', '', '', '', NULL, NULL, 'active', 0, 0, '0.00', '2026-04-17 01:28:27', '2026-04-17 01:28:27'),
(73, 3, 'Artifacts- Lusong', 'artifacts-lusong', 'Lusong (wooden mortar) is a powerful symbol of the town&#039;s agricultural roots and communal strength.\r\n​Carved from a single, sturdy log of hardwood, this mortar was once the heartbeat of the Ilonggo home. In the farming villages of San Enrique, it was used with a heavy wooden pestle to pound rice or grind corn, a task that required great physical endurance. The rhythmic sound of the lusong echoed through the fields, signaling the preparation of the day&#039;s meal or the bounty of a fresh harvest.\r\n​Today, this weathered artifact stands as a tribute to the grit and self-sufficiency of the town’s ancestors, honoring the hardworking spirit that built the community.', '', '', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=144zpl-yaG0PfjX_RAbo1YgQQEPHLG24n&sz=w1200', '[]', '', '', '', '', NULL, NULL, 'active', 0, 0, '0.00', '2026-04-17 01:31:19', '2026-04-17 01:31:19'),
(74, 3, 'Artifact-Petromax', 'artifact-petromax', 'Petromax (kerosene pressure lamp) is a nostalgic symbol of light and hospitality in traditional Ilonggo homes.\r\n​Before widespread rural electrification, these heavy, high-powered lamps were the brightest light source in a household. In the farming community of San Enrique, the gisi (hissing sound) of the Petromax marked the gathering of the family for dinner, long conversations into the night, or crucial all-night work during harvest seasons. It required skill to operate, involving pumping pressure into the tank to vaporize the fuel.\r\n​Now preserved as a cultural relic, the Petromax stands as a tribute to the resilience and warmth of the town’s ancestors, symbolizing the light that brought the community together.', '', '', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1tpqEfiaGw469OYEjxhsx35lGwYsmXZ4D&sz=w1200', '[]', '', '', '', '', NULL, NULL, 'active', 0, 0, '0.00', '2026-04-17 01:34:44', '2026-04-17 01:34:44'),
(75, 3, 'Artifacts-stone mill,', 'artifacts-stone-mill', '<p>Galingan nga bato/stone mill, in the heritage context of San Enrique, Iloilo, the Gilingan nga Bato (stone grinder) is a timeless symbol of traditional Ilonggo culinary skill.<br>​Hand-carved from heavy stone, these grinders were once the heart of the kitchen, used to transform soaked rice into galapong for local favorites like puto and bibingka. In the rural homes of San Enrique, the rhythmic sound of the stone was a sign of preparation for town fiestas and family gatherings.<br>​Today, these artifacts represent the patience and authenticity of the town’s ancestors, honoring a time when every meal was crafted with labor, love, and natural ingredients</p>', '', '', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1YYrQEsloB_3MnHRmeQPhqNTKVOaU83nP&sz=w1200', '[]', '', '', '', '', '', '', 'active', 0, 0, '0.00', '2026-04-17 01:55:19', '2026-05-25 01:39:10'),
(76, 3, 'White Cross (Cross of Salvation)', 'white-cross-cross-of-salvation', 'White Cross (Cross of Salvation) is a prominent, towering pillar located in <span class=\"Yjhzub\" jsaction=\"\" jscontroller=\"zYmgkd\" data-sfc-root=\"c\" jsuid=\"crk2Pb_1r\" data-sfc-cb=\"\" data-complete=\"true\" data-copy-service-computed-style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif;font-weight: 600; margin: 0px; text-decoration: none; border-bottom: 0px rgb(230, 232, 240);\" style=\"font-family: &quot;Google Sans&quot;, Arial, sans-serif; font-weight: 600; border-bottom: 0px rgb(230, 232, 240);\">San Enrique, Iloilo, Philippines<!--TgQPHd|[]--></span>. It functions as a local sanctuary for prayers, spiritual reflection, and devotion.<!--EndFragment--> <span style=\"font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; white-space: pre-wrap;\">Beyond that, it’s also a popular photo spot because it usually sits in an open area with a wide view of the valley, mountains, or town below. It’s simple in design but stands out against the landscape</span><!--EndFragment-->', '', 'Paga', '', '', '', NULL, NULL, 'https://scontent.fceb2-2.fna.fbcdn.net/v/t39.30808-6/706794240_122112323139072244_8555198464437595920_n.jpg?stp=cp6_dst-jpg_tt6&_nc_cat=102&ccb=1-7&_nc_sid=127cfc&_nc_eui2=AeG-TqeLiPivEL57VaNXplpTr_8O9OLm8J2v_w704ubwnUvYcU1E0E_O0UHRPCX-6CL-PdubhK_919AsmlamZcIZ&_nc_ohc=OBLp-W-JPL8Q7kNvwFl7ATY&_nc_oc=AdpbiO71OP22OKNu0_QAZ94WEbCCQ7cME-SyMvmnAhODHf-GiQWXx-u2GnV2qUgq7Ak&_nc_zt=23&_nc_ht=scontent.fceb2-2.fna&_nc_gid=jnr52b9f85WkAqeXTqVFZg&_nc_ss=7b2a8&oh=00_Af4Ngbp84jXThT2nmOXFU3VYhbp1U2rGTt8Hotdh4Cfv', '[\"https:\\/\\/scontent.fceb2-2.fna.fbcdn.net\\/v\\/t39.30808-6\\/706831354_122112323289072244_6452319369642895252_n.jpg?stp=cp6_dst-jpg_s590x590_tt6&_nc_cat=102&ccb=1-7&_nc_sid=127cfc&_nc_eui2=AeFdi4O5GnsZ6k3rXlKFCfvbrufkxglQoBOu5-TGCVCgExbBTkQ9fFTfB4U4O-Bfuqi4eD1COZOiRO7UmJ3ZlOyV&_nc_ohc=6IxjNUXmK9gQ7kNvwHB-FxC&_nc_oc=AdooThe4i8