eui2=AeGWJv45OVzNIxaEXOELaBFWXYmgZV0Zz-5diaBlXRnP7pZ6lrZpHBOZGQQvN8VQsv9ACLCgEljFuEMyvGHhG1_T&_nc_ohc=vebY25pbhZEQ7kNvwEPkmlL&_nc_oc=Adp-676uj-HU6EhNmg-pD8fdrRAs7VOopvqUYJWo8w6bXQ1JkkHZkgWYYYfEUH8pBok&_nc_zt=23&_nc_ht=scontent.fceb6-3.fna&_nc_gid=2idOBbP8obFN6Rw14DK01Q&_nc_ss=7b2a8&oh=00_Af5SC2QgAh7yVFtXVzgK7WjmbGnz1oOmKb89CeZ7KTZY3g&oe=6A19728D\",\"https:\\/\\/scontent.fceb6-1.fna.fbcdn.net\\/v\\/t39.30808-6\\/706966035_122112323511072244_1387316649588805232_n.jpg?stp=cp6_dst-jpg_tt6&_nc_cat=105&ccb=1-7&_nc_sid=127cfc&_nc_eui2=AeGxuONB_zukndn3Ab6L2mArbZKy0CO7F0xtkrLQI7sXTHGUPPtiGZ0MicmHHSoAO-sQY4PmQJet4rWlFI_dH6kE&_nc_ohc=bUQPiI6pXa4Q7kNvwHv0mcK&_nc_oc=AdpVxgGRI3YxNXFhVM9rXvCJROrMFTNfJSiei3wPP0-m_PhF6rZi7ovv_Y2_lpMVS84&_nc_zt=23&_nc_ht=scontent.fceb6-1.fna&_nc_gid=dELPAmcZpi91mqQ8gVonkw&_nc_ss=7b2a8&oh=00_Af5jItu0tIFSKI4nrYd2vN_5wE03CRuGYbSAx6zqnluG1A&oe=6A197320\"]', '', '', '', '', '', '', 'active', 0, 6, '0.00', '2026-05-25 03:01:52', '2026-05-25 07:16:12'),
(77, 5, 'Brgy. Braulan Vegetable Garden', 'brgy-braulan-vegetable-garden', '<!--StartFragment-->The vegetable garden in <b data-path-to-node=\"0\" data-index-in-node=\"24\">Barangay Braulan</b>, located in the agricultural municipality of <b data-path-to-node=\"0\" data-index-in-node=\"86\">San Enrique, Iloilo</b>, stands as a shining example of community-led food security and sustainable farming. Part of the broader <i data-path-to-node=\"0\" data-index-in-node=\"211\">Gulayan sa Barangay</i> (Village Vegetable Garden) initiatives promoted across the province, this communal garden showcases local cooperation and self-reliance.<!--EndFragment-->', 'Barangay Braulan, San Enrique, Iloilo', 'Braulan', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1vG_WI4lz5JNK4HA5-0oxX8EBxkfS-t4-&sz=w1200', '[\"https:\\/\\/drive.google.com\\/thumbnail?id=1J9-93Tvzw3r9RFII54FOJ7noSLjZIZ9m&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1EGnzeVcZk-1W5MZZcKmEz17q_hge-bMD&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1WTs6gwcyYJUALzZSoasoPqD6WqgsPdeA&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1SrC2qQbDeupU0NwLj6EmDrbO-zYbUOGm&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1JKrwSOcHvczkYc1w_G82b_ELTX_xmshn&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1XssnRPy5wvLjOyudNAacoBNTDDTMROI5&sz=w1200\"]', '', '', '', '', '', '', 'active', 0, 0, '0.00', '2026-05-25 03:06:32', '2026-05-25 03:06:32'),
(79, 3, 'Brgy. Abaca Hanging Bridge', 'brgy-abaca-hanging-bridge', '<!--StartFragment-->Suspended high above a rushing river, this rustic hanging bridge bridges the gap between nature and adventure. Crafted from a mix of steel pipes and sturdy cables, it offers a thrilling, gentle sway with every footstep. Walking across rewards you with a panoramic view of lush tropical banks, sweeping green fields, and the cool water flowing beneath—a perfect snapshot of quiet countryside charm.<!--EndFragment-->', 'Barangay Abaca, San Enrique, Iloilo', 'Abaca', '', '', '', NULL, NULL, 'https://drive.google.com/thumbnail?id=1J0R_od_gY-Zuq6GbmKqA0A7hBpHVe9V5&sz=w1200', '[\"https:\\/\\/drive.google.com\\/thumbnail?id=1yiYUYmMSPVaPA6Tl6m453Q9D6OFk5Hwn&sz=w1200\",\"https:\\/\\/drive.google.com\\/thumbnail?id=1zLxCWKRLuDiHSgNOAlZ-CbM10g72klSN&sz=w1200\"]', '', '', '', '', '', '', 'active', 0, 4, '0.00', '2026-05-25 03:24:07', '2026-05-25 06:27:48'),
(80, 2, 'Barangay Abaca', 'barangay-abaca', '<!--StartFragment--><span style=\"font-family: \" segoe=\"\" ui=\"\" historic\",=\"\" \"segoe=\"\" ui\",=\"\" helvetica,=\"\" arial,=\"\" sans-serif;=\"\" white-space:=\"\" pre-wrap;\"=\"\">Is a mid-sized barangay in the municipality of San Enrique, located in the province of Iloilo, in the Western Visayas region of the Philippines. Barangay Abaca had a population of 2,957. This made it the 1st largest of 28 barangays in San Enrique by population, placing it among the most populous barangays of the municipality. Residents of Barangay Abaca accounted for approximately 7.91% of the total population of San Enrique. </span><div><span style=\"font-family: \" segoe=\"\" ui=\"\" historic\",=\"\" \"segoe=\"\" ui\",=\"\" helvetica,=\"\" arial,=\"\" sans-serif;=\"\" white-space:=\"\" pre-wrap;\"=\"\"><b>Officials: </b></span></div><div><span style=\"font-family: \" segoe=\"\" ui=\"\" historic\",=\"\" \"segoe=\"\" ui\",=\"\" helvetica,=\"\" arial,=\"\" sans-serif;=\"\" white-space:=\"\" pre-wrap;\"=\"\"><i>Barangay\r\nEdgardo Guillen Caballero </i></span></div><div><span style=\"font-family: \" segoe=\"\" ui=\"\" historic\",=\"\" \"segoe=\"\" ui\",=\"\" helvetica,=\"\" arial,=\"\" sans-serif;=\"\" white-space:=\"\" pre-wrap;\"=\"\"><i>Barangay Secretary</i></span></div><div><span style=\"font-family: \" segoe=\"\" ui=\"\" historic\",=\"\" \"segoe=\"\" ui\",=\"\" helvetica,=\"\" arial,=\"\" sans-serif;=\"\" white-space:=\"\" pre-wrap;\"=\"\"><i> Alona Jolampong Chavez </i></span></div><div><span style=\"font-family: \" segoe=\"\" ui=\"\" historic\",=\"\" \"segoe=\"\" ui\",=\"\" helvetica,=\"\" arial,=\"\" sans-serif;=\"\" white-space:=\"\" pre-wrap;\"=\"\"><i>SK Chairperson\r\nJesmar Sumindol Alarba </i></span></div><div><span style=\"font-family: \" segoe=\"\" ui=\"\" historic\",=\"\" \"segoe=\"\" ui\",=\"\" helvetica,=\"\" arial,=\"\" sans-serif;=\"\" white-space:=\"\" pre-wrap;\"=\"\"><b>Sangguniang Barangay Members (Kagawads) </b></span></div><div><span style=\"font-family: \" segoe=\"\" ui=\"\" historic\",=\"\" \"segoe=\"\" ui\",=\"\" helvetica,=\"\" arial,=\"\" sans-serif;=\"\" white-space:=\"\" pre-wrap;\"=\"\"><i>•Jae-ann Acollador Daquiado </i></span></div><div><span style=\"font-family: \" segoe=\"\" ui=\"\" historic\",=\"\" \"segoe=\"\" ui\",=\"\" helvetica,=\"\" arial,=\"\" sans-serif;=\"\" white-space:=\"\" pre-wrap;\"=\"\"><i>•Myrna Sumagaysay Buyco</i></span></div><!--StartFragment--><!--EndFragment--><div><span style=\"font-family: \" segoe=\"\" ui=\"\" historic\",=\"\" \"segoe=\"\" ui\",=\"\" helvetica,=\"\" arial,=\"\" sans-serif;=\"\" white-space:=\"\" pre-wrap;\"=\"\"><i>•Jessebel Agujetas Sumindol </i></span></div><div><span style=\"font-family: \" segoe=\"\" ui=\"\" historic\",=\"\" \"segoe=\"\" ui\",=\"\" helvetica,=\"\" arial,=\"\" sans-serif;=\"\" white-space:=\"\" pre-wrap;\"=\"\"><i>•John Devecais Balboa </i></span></div><!--StartFragment--><!--EndFragment--><div><span style=\"font-family: \" segoe=\"\" ui=\"\" historic\",=\"\" \"segoe=\"\" ui\",=\"\" helvetica,=\"\" arial,=\"\" sans-serif;=\"\" white-space:=\"\" pre-wrap;\"=\"\"><i>•Rodelito Daborbor Daquiado </i></span></div><div><span style=\"font-family: \" segoe=\"\" ui=\"\" historic\",=\"\" \"segoe=\"\" ui\",=\"\" helvetica,=\"\" arial,=\"\" sans-serif;=\"\" white-space:=\"\" pre-wrap;\"=\"\"><i>•Jesus Alumbro Acollador</i></span></div><div><span style=\"font-family: \" segoe=\"\" ui=\"\" historic\",=\"\" \"segoe=\"\" ui\",=\"\" helvetica,=\"\" arial,=\"\" sans-serif;=\"\" white-space:=\"\" pre-wrap;\"=\"\"><i>•Nilo Edaño Alarba</i></span><!--EndFragment--></div>', 'Barangay Abaca, San Enrique, Iloilo', 'Abaca', '', '', '', '11.12882023', '122.71468266', 'https://drive.google.com/thumbnail?id=1gl3LLyeFmp_6SNoI5spY394jg7gbnIZx&sz=w1200', '[]', '', '', '', '', '11 km', '2,957', 'active', 0, 17, '0.00', '2026-05-25 05:48:25', '2026-06-01 02:11:10'),
(82, 4, 'Rosita Papaya Crema de Leche', 'rosita-papaya-crema-de-leche', '<!--StartFragment--><span style=\"font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; white-space: pre-wrap;\">Rosita Papaya Crema de Leche (also known as Papaya Rosette or Dinulce nga Kapayas) is a cherished, artisanal delicacy from San Enrique, Iloilo. It is a hand-crafted sweet made from thinly shaved, green papaya caramelized in sugar, painstakingly shaped into delicate flower petals. This delicacy reflects the agricultural bounty of San Enrique and requires intense labor and skill to produce, often available through local specialty makers like Nanay Emang\'s Delicacies.</span><!--EndFragment-->', 'Barangay Cabugao Viejo, San Enrique, Iloilo', 'Cabugao Viejo', '', '', '', NULL, NULL, 'https://scontent.fceb6-1.fna.fbcdn.net/v/t39.30808-6/706780449_122112332019072244_1383909008077430340_n.jpg?_nc_cat=104&ccb=1-7&_nc_sid=127cfc&_nc_eui2=AeEm82a8p6UALCLVnOy3lVDhPTfUx7jVBWg9N9THuNUFaIK_XTskgMUMNDj6dxnoJ93XKixnAqXgcQymmLCE2GGu&_nc_ohc=VW05VRsdSvMQ7kNvwGcYszE&_nc_oc=AdpP3kFikqTrNUzdj9pkpgksEogCbwhOvDcruAsAxImBr3YiwquQkwzdI-bO7Gsxab0&_nc_zt=23&_nc_ht=scontent.fceb6-1.fna&_nc_gid=EB641ct60qCKPOyItOsXwg&_nc_ss=7b2a8&oh=00_Af6oUqXaVwgG_B1SESaxBfPEXQjP2nA1Z0IxTtKXuJgHCw&oe=6A19B9AB', '[]', '', '', 'Market price', '', '', '', 'active', 0, 0, '0.00', '2026-05-25 06:08:57', '2026-05-25 06:08:57');


